#include <stdlib.h>
#include <string.h>
#include <math.h>

// Forward auction with epsilon scaling.
// C: n x n cost matrix (row-major, double), person i -> object j.
// Returns assignment array (person -> object), caller allocates n ints.
void auction_solve(const double *C, int n, int *person_obj) {
    double *p = (double*)calloc(n, sizeof(double));
    int *assign = (int*)malloc(n * sizeof(int)); // object -> person
    int *stack = (int*)malloc(n * sizeof(int));
    for (int j = 0; j < n; j++) assign[j] = -1;
    for (int i = 0; i < n; i++) person_obj[i] = -1;

    // find max cost
    double cmax = 0.0;
    for (int k = 0; k < n*n; k++) if (C[k] > cmax) cmax = C[k];

    double eps = cmax / 2.0;
    while (eps > 1e-9) {
        // reset assignments, keep prices
        for (int j = 0; j < n; j++) assign[j] = -1;
        for (int i = 0; i < n; i++) person_obj[i] = -1;
        int top = 0;
        for (int i = 0; i < n; i++) stack[top++] = i;
        while (top > 0) {
            int i = stack[--top];
            const double *row = C + (size_t)i * n;
            double v1 = -1e300, v2 = -1e300;
            int j1 = -1;
            for (int j = 0; j < n; j++) {
                double v = -row[j] - p[j];
                if (v > v1) { v2 = v1; v1 = v; j1 = j; }
                else if (v > v2) { v2 = v; }
            }
            double bid = v1 - v2 + eps;
            p[j1] += bid;
            int prev = assign[j1];
            assign[j1] = i;
            person_obj[i] = j1;
            if (prev != -1) {
                person_obj[prev] = -1;
                stack[top++] = prev;
            }
        }
        eps /= 2.0;
    }
    free(p); free(assign); free(stack);
}
