import numpy as np, time, ctypes
from scipy.optimize import linear_sum_assignment
from reference import Task

lib = ctypes.CDLL('./auction.so')
lib.auction_solve.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.POINTER(ctypes.c_int)]
lib.auction_solve.restype = None

def solve_c(M):
    n = M.shape[0]
    C = np.ascontiguousarray(M, dtype=np.float64)
    pa = np.zeros(n, dtype=np.int32)
    lib.auction_solve(C.ctypes.data_as(ctypes.POINTER(ctypes.c_double)), n, pa.ctypes.data_as(ctypes.POINTER(ctypes.c_int)))
    return pa

t = Task()
for seed in range(3):
    p = t.generate_problem(n=600, random_seed=seed)
    M = np.ascontiguousarray(p['cost_matrix'], dtype=np.float64)
    ri, ci = linear_sum_assignment(M)
    scipy_assign = np.full(600, -1, dtype=np.int64)
    scipy_assign[ri] = ci
    t0=time.perf_counter()
    pa = solve_c(M)
    dt=time.perf_counter()-t0
    print('seed', seed, 'time', dt, 'match', np.array_equal(pa, scipy_assign))
