    pa = np.zeros(n, dtype=np.int32)
    lib.auction_solve(C.ctypes.data_as(ctypes.POINTER(ctypes.c_double)), n, eps_min, pa.ctypes.data_as(ctypes.POINTER(ctypes.c_int)))
